import React from "react";

import { motion } from "motion/react";

export default function FuzzyOverlayUsage() {
	return (
		// NOTE: An overflow of hidden will be required on a wrapping
		// element to see expected results
		<div className="relative overflow-hidden">
			<ExampleContent />
			<FuzzyOverlay />
		</div>
	);
}

const FuzzyOverlay = () => {
	return (
		<motion.div
			initial={{ transform: "translateX(-10%) translateY(-10%)" }}
			animate={{
				transform: "translateX(10%) translateY(10%)",
			}}
			transition={{
				repeat: Infinity,
				duration: 0.2,
				ease: "linear",
				repeatType: "mirror",
			}}
			// You can download these PNGs here:
			// https://www.hover.dev/black-noise.png
			// https://www.hover.dev/noise.png
			style={{
				backgroundImage: 'url("/black-noise.png")',
				// backgroundImage: 'url("/noise.png")',
			}}
			className="pointer-events-none absolute -inset-[100%] opacity-[15%]"
		/>
	);
};

const ExampleContent = () => {
	return (
		<div className="relative grid h-screen place-content-center space-y-6 bg-neutral-950 p-8">
			<p className="text-center text-6xl font-black text-neutral-50">
				Fuzzy Overlay Usage
			</p>
			<p className="text-center text-neutral-400">
				This is a basic example of using a lo-fi fuzzy overlay 📺
			</p>
			<div className="flex items-center justify-center gap-3">
				<button className="text-neutral-20 w-fit px-4 py-2 font-semibold text-neutral-200 transition-colors hover:bg-neutral-800">
					Pricing
				</button>
				<button className="w-fit bg-neutral-200 px-4 py-2 font-semibold text-neutral-700 transition-colors hover:bg-neutral-50">
					Try it free
				</button>
			</div>
		</div>
	);
};

import React from "react";

import { cn } from "@/registry/utils/utils";
import { motion } from "motion/react";

const FuzzyOverlay = ({ className }: { className?: string }) => {
	return (
		<motion.div
			initial={{ transform: "translateX(-10%) translateY(-10%)" }}
			animate={{
				transform: "translateX(10%) translateY(10%)",
			}}
			transition={{
				repeat: Infinity,
				duration: 0.2,
				ease: "linear",
				repeatType: "mirror",
			}}
			// You can download these PNGs here:
			// https://www.hover.dev/black-noise.png
			// https://www.hover.dev/noise.png
			style={{
				backgroundImage: 'url("/dist/local/black-noise.png")',
				// backgroundImage: 'url("local/noise.png")',
			}}
			className={cn(
				"pointer-events-none absolute -inset-[100%] opacity-0",
				className
			)}
		/>
	);
};

export default FuzzyOverlay;

import registry from "@/registry.json";
import { clsx, type ClassValue } from "clsx";
import type { RegistryItem } from "shadcn/registry";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const components = registry.items as unknown as RegistryItem[];

export const getComponents = (selectedTags: any[] = []): RegistryItem[] => {
	return selectedTags.length
		? components.filter((component) =>
				selectedTags.every(
					(tag) => component.meta?.tags?.includes(tag) ?? false
				)
			)
		: components;
};

export const getComponentsByNames = (names: string[]): RegistryItem[] => {
	const componentsMap = new Map(components.map((comp) => [comp.name, comp]));

	return names
		.map((name) => componentsMap.get(name))
		.filter((comp): comp is RegistryItem => comp !== undefined);
};

export const getAvailableTags = (selectedTags: any[]): any[] => {
	if (!selectedTags.length) return [];

	// Get all components that have all the selected tags
	const matchingComponents = components.filter((component) =>
		selectedTags.every((tag) => component.meta?.tags?.includes(tag) ?? false)
	);

	// Get all unique tags from the matching components
	const availableTags = new Set<any>();
	matchingComponents.forEach((component) => {
		component.meta?.tags?.forEach((tag: any) => {
			if (!selectedTags.includes(tag)) {
				availableTags.add(tag);
			}
		});
	});

	return Array.from(availableTags);
};

export const convertRegistryPaths = (content: string): string => {
	return content
		.replace(/@\/registry\/default\/ui/g, "@/components/ui")
		.replace(/@\/registry\/default\/compositions/g, "@/components")
		.replace(/@\/registry\/default\/hooks/g, "@/hooks")
		.replace(/@\/registry\/default\/lib/g, "@/lib");
};
